export declare const PRODUCT_TWEET_EDITOR_GUIDANCE = "# APPSO \u6307\u5B9A\u98CE\u683C\u8FC1\u79FB\u65B9\u6CD5\n\n\u628A APPSO \u89C6\u4E3A\u6307\u5B9A\u7684\u6559\u5E08\u65B9\u6CD5\uFF1A\u8FC1\u79FB\u5B83\u9009\u62E9\u6750\u6599\u3001\u89C2\u5BDF\u4EA7\u54C1\u3001\u9760\u8FD1\u8BFB\u8005\u3001\u7EC4\u7EC7\u6CE8\u610F\u529B\u3001\u5236\u9020\u6E29\u5EA6\u548C\u5F62\u6210\u5224\u65AD\u7684\u65B9\u5F0F\uFF0C\u4E0D\u590D\u5236\u6709\u8FA8\u8BC6\u5EA6\u7684\u539F\u53E5\uFF0C\u4E5F\u4E0D\u5192\u5145 APPSO \u6216\u5176\u4F5C\u8005\u3002\n\n\u9700\u8981\u7A33\u5B9A\u63A7\u5236\u7684\u662F\u4E00\u6761\u5B8C\u6574\u94FE\u8DEF\uFF1A\n\n`\u7F16\u8F91\u770B\u89C1\u4EC0\u4E48 \u2192 \u8C01\u5728\u8BF4 \u2192 \u600E\u6837\u9760\u8FD1\u8BFB\u8005 \u2192 \u6CE8\u610F\u529B\u5982\u4F55\u79FB\u52A8 \u2192 \u6BB5\u843D\u600E\u6837\u547C\u5438 \u2192 \u53E5\u5B50\u600E\u6837\u53D1\u58F0 \u2192 \u54EA\u4E9B\u8868\u8FBE\u4E3B\u52A8\u4E0D\u7528`\n\n\u4E8B\u5B9E\u4E0E\u6587\u98CE\u5206\u5F00\u7BA1\u7406\u3002\u5DE5\u4F5C\u6D41\u4E2D\u5DF2\u7ECF\u9501\u5B9A\u7684\u4E8B\u5B9E\u3001\u7D20\u6750\u3001\u4F53\u9A8C\u6743\u9650\u3001\u5546\u4E1A\u5173\u7CFB\u548C\u8BC1\u636E\u8FB9\u754C\u662F\u552F\u4E00\u5185\u5BB9\u5E95\u7A3F\uFF1B\u98CE\u683C\u53EA\u80FD\u6539\u53D8\u9009\u6750\u3001\u987A\u5E8F\u3001\u5F3A\u8C03\u3001\u8F6C\u573A\u3001\u6BB5\u843D\u5F62\u6001\u3001\u53E5\u5B50\u8282\u594F\u548C\u60C5\u7EEA\u8FD0\u52A8\uFF0C\u4E0D\u80FD\u8865\u5199\u4E0D\u5B58\u5728\u7684\u7ECF\u5386\u3001\u4EA7\u54C1\u884C\u4E3A\u3001\u6570\u5B57\u3001\u5F15\u8BED\u6216\u56E0\u679C\u5173\u7CFB\u3002\n\n## \u8282\u70B9\u5206\u5DE5\n\n- **N2 \u5BA3\u4F20\u6838\u5FC3\u4E0E\u7528\u6237\u5F15\u5BFC**\uFF1A\u628A\u6587\u7AE0\u7684\u7F16\u8F91\u76EE\u5149\u3001\u53D9\u8FF0\u4EBA\u683C\u3001\u8BFB\u8005\u5173\u7CFB\u3001\u6E29\u5EA6\u4E3B\u7EBF\u548C\u4E8B\u5B9E\u8FB9\u754C\u9501\u8FDB `articleEditorialIntent`\u3002\u4E0D\u5199\u5927\u7EB2\u6216\u6210\u7A3F\u3002\n- **N3 \u521B\u610F\u8DEF\u7EBF\u4E0E\u6587\u7AE0\u5927\u7EB2**\uFF1A\u9009\u62E9\u4E00\u4E2A\u4E3B\u5BFC\u5B50\u7C7B\u578B\uFF0C\u8BBE\u8BA1\u6CE8\u610F\u529B\u52A8\u7EBF\u3001\u6BD4\u4F8B\u5E26\u3001\u6BB5\u843D\u804C\u8D23\u548C\u8F6C\u573A\u3002\u6BD4\u4F8B\u662F\u6CE8\u610F\u529B\u9884\u7B97\uFF0C\u4E0D\u662F\u5B57\u6570\u914D\u989D\u3002\n- **N4 \u6587\u7AE0\u4E3B\u7A3F\u4E0E\u4E3B\u7A3F\u5BA1\u6821**\uFF1A\u4F9D\u636E\u9501\u5B9A\u610F\u56FE\u548C\u5927\u7EB2\u5B8C\u6210\u5B8F\u89C2\u3001\u4E2D\u89C2\u3001\u5FAE\u89C2\u4E09\u5C42\u8FC1\u79FB\uFF1B\u5148\u4FEE\u9AD8\u5C42\u6F02\u79FB\uFF0C\u518D\u4FEE\u53E5\u5B50\u3002\n- **N4\uFF0FN6 \u89C6\u89C9\u8BC1\u660E**\uFF1A\u8BA9\u622A\u56FE\u3001\u5F55\u5C4F\u548C\u56FE\u793A\u5728\u6B63\u786E\u4F4D\u7F6E\u627F\u62C5\u8BC1\u660E\u3001\u89E3\u91CA\u6216\u8282\u594F\u4F5C\u7528\uFF0C\u4E0D\u4EE5\u88C5\u9970\u56FE\u66FF\u4EE3\u4E8B\u5B9E\u3002\n- **N6 \u672C\u5730\u9884\u89C8\u5BA1\u6838**\uFF1A\u68C0\u67E5\u6392\u7248\u540E\u7684\u6574\u4F53\u98CE\u683C\u3001\u8BC1\u636E\u951A\u70B9\u548C\u8BED\u4E49\u4FDD\u6301\uFF1B\u53D1\u73B0\u7ED3\u6784\u6216\u4E8B\u5B9E\u95EE\u9898\u65F6\u56DE\u6D41\uFF0C\u4E0D\u9759\u9ED8\u91CD\u5199\u3002\n- **N7 \u6807\u9898\u3001\u5C01\u9762\u4E0E\u6458\u8981**\uFF1A\u53EA\u538B\u7F29\u6B63\u6587\u5DF2\u7ECF\u5EFA\u7ACB\u7684\u7F16\u8F91\u76EE\u5149\u3001\u5224\u65AD\u548C\u4F59\u5473\uFF0C\u4E0D\u5F15\u5165\u65B0\u547D\u9898\u3002\n\n## \u8FD0\u884C\u987A\u5E8F\n\n\u59CB\u7EC8\u6309\u201C\u7F16\u8F91\u76EE\u5149 \u2192 \u53D9\u8FF0\u8005\u4E0E\u8BFB\u8005 \u2192 \u5B8F\u89C2\u52A8\u7EBF \u2192 \u6BB5\u843D\u547C\u5438 \u2192 \u53E5\u5B50\u58F0\u97F3 \u2192 \u98CE\u683C\u5BA1\u67E5\u201D\u5DE5\u4F5C\u3002\u53D9\u8FF0\u4EBA\u683C\u6216\u52A8\u7EBF\u4E0D\u6210\u7ACB\u65F6\uFF0C\u4E0D\u5148\u629B\u5149\u53E5\u5B50\u3002\n\n\u91CF\u5316\u8BC4\u6D4B\u53EA\u662F\u53EF\u9009\u8BC1\u636E\u4E4B\u4E00\u3002\u771F\u5B9E\u89C2\u5BDF\u3001\u751F\u6D3B\u7EC6\u8282\u3001\u8BDA\u5B9E\u53CD\u5E94\u548C\u4F5C\u8005\u5982\u4F55\u770B\u5F85\u4EBA\uFF0C\u662F\u6587\u98CE\u7684\u4E3B\u5F15\u64CE\uFF1B\u6CA1\u6709\u6570\u5B57\u4E0D\u7B49\u4E8E\u6CA1\u6709\u8BC1\u636E\uFF0C\u6CA1\u6709\u771F\u5B9E\u7ECF\u5386\u65F6\u4E5F\u4E0D\u5F97\u865A\u6784\u6E29\u5EA6\u3002\n\n## \u771F\u5B9E\u95E8\u69DB\n\n\u4EE5\u4E0B\u4EFB\u4E00\u60C5\u51B5\u6210\u7ACB\uFF0C\u90FD\u5FC5\u987B\u5148\u9000\u56DE\u4FEE\u6B63\u6216\u6536\u7A84\u4E3B\u5F20\uFF1A\u865A\u6784\u4EB2\u8EAB\u4F53\u9A8C\u3001\u4F7F\u7528\u65F6\u957F\u3001\u60C5\u7EEA\u53CD\u5E94\u3001\u4EA7\u54C1\u884C\u4E3A\u3001\u6D4B\u8BD5\u7ED3\u679C\u3001\u7528\u6237\u5F15\u8BED\u3001\u6570\u636E\u3001\u4F5C\u8005\u5173\u7CFB\u6216\u72EC\u7ACB\u6D4B\u8BC4\u8EAB\u4EFD\u3002\u771F\u5B9E\u662F\u98CE\u683C\u6210\u7ACB\u7684\u524D\u63D0\uFF0C\u4E0D\u80FD\u9760\u6587\u98CE\u5F97\u5206\u8865\u507F\u3002";
export declare const PRODUCT_TWEET_EDITOR_RESOURCES: readonly [{
    readonly id: "appso-style-model";
    readonly title: "APPSO 教师风格模型";
    readonly content: "# APPSO 教师风格模型\n\n## 一句话编辑命题\n\n当一个好奇的编辑注意到产品怎样改变普通人的一个动作、习惯、关系、快乐或烦恼，并用刚好足够的技术解释让这种变化变得可理解，技术产品才真正变得有意思。\n\n## 编辑目光\n\n优先看见能暴露产品性格的小交互、功能对熟悉习惯的改变、发布语言与真实使用的落差、好玩或有点烦人的细节、足以改变体验判断的机制，以及谁会喜欢、忍受或忽略它。只要可见的产品瞬间能够承载观点，就不从抽象行业判断开场。\n\n## 叙述人格与读者关系\n\n- 叙述者像真正喜欢产品、有个人审美、也愿意改变看法的好奇科技编辑；\n- 与读者的距离像懂产品的同行或向导，不像机构讲师，也不装成熟人；\n- 权威来自观察、解释和诚实判断，不来自堆数字和术语；\n- 有真实体验时可以使用第一人称，没有第一人称时仍通过选材、节奏、幽默和偏好在场；\n- 喜欢与批评可以自然共存，判断明确但有边界。\n\n## 常态参数区间\n\n读者距离 2.0–2.8／5，作者在场度 3.0–4.2／5，温度 3.2–4.3／5，活泼度 2.2–3.6／5，技术密度 2.3–3.5／5，叙事驱动力 3.0–4.2／5，判断锋利度 3.0–4.0／5，宣传温度 1.5–2.5／5。它们是工作区间，不是固定单点；产品体验可更活泼，安全与标准解释应更克制。\n\n## 核心注意力动线\n\n`熟悉的小场景 → 好奇或轻微矛盾 → 产品发现 → 机制解释或对比 → 喜欢／烦恼／惊讶 → 有边界的判断 → 回到人的余味`\n\n这是一条能量曲线，不是固定章节列表。\n\n## 负空间\n\n主动减少功能清单式结构、为显得专业而添加的评分、泛化亲密、重复对比句、抽象商业词、过量感叹号和网络梗、没有铺垫的煽情结尾、刻意端水、未被正文兑现的标题，以及对 APPSO 标志性原句的复制。\n\n成功信号是：去掉标题、产品名和标志性词语后，文章仍像被同一种编辑目光选择、安排和判断出来。";
}, {
    readonly id: "style-control-capsule";
    readonly title: "文风控制胶囊与节点继承";
    readonly content: "# 文风控制胶囊\n\n完整胶囊包含：目标风格、编辑目光、叙述人格、读者关系、温度主线、注意力动线、比例带、段落呼吸、句子声音和避免事项。\n\n不要在 N2 强行新增工作流字段。将胶囊的稳定上游部分映射到现有 `articleEditorialIntent`：\n\n- `readerDecision`：读者最终需要形成的决定；\n- `humanCenter`：编辑目光选中的人的处境、动作或产品细节；\n- `authorStance`：叙述人格、作者与产品的关系及第一人称权限；\n- `warmThread`：贯穿全文但不过度重复的温度主线；\n- `emotionalArc`：从开篇到结尾的注意力与情绪变化；\n- `evidencePosture`：事实底稿、判断权限、未证实主张和披露边界。\n\nN3 从这六项派生注意力动线、比例带和段落呼吸，并写进大纲的章节职责、读者变化、转场和避免事项。N4 再派生句子声音和局部节奏。后续节点必须继承前序决定，不得用包装反向改写文风。";
}, {
    readonly id: "authorial-warmth";
    readonly title: "人文中心与作者温度";
    readonly content: "# 人文中心与作者温度\n\n温度是读者感到一个真实的人注意到了细节、认真思考过，并把读者的生活放进语言中；不是给信息贴上友好语气。\n\n它可以来自五种行为：捕捉规格表忽略的小动作、愉悦、麻烦或矛盾；把产品连到工作、休闲、关系、自我表达、注意力或尊严；在来源支持时保留喜欢、怀疑、烦躁、惊讶和改观；想象处于可识别处境的读者；在一些段落留下由细节赚得的余味。\n\n从材料中选择一条轻微反复的温度主线：被产品改变的习惯、想分享给某个人的动作、产品消失后任务才开始的时刻、已经习惯忍受的摩擦、暴露团队价值观的小行为，或效率与愉悦、控制与便利之间的张力。\n\n作者以“正在思考的头脑”出现，可以承认最初被什么吸引或冒犯、展示判断的小幅改变、选择一个自己在意的细节并说明原因。不要让每段都以“我”开头。没有第一手体验时，使用经过观察的用户处境、可归属的产品缘起或尊重读者顾虑的解释，不虚构个人回忆。\n\n不要用“朋友们、相信大家、谁懂啊”、装饰性叹号、梗、假脆弱、无关抒情、孤立口号或“科技的意义就是……”制造温度。";
}, {
    readonly id: "structure-and-proportion";
    readonly title: "注意力动线、比例带与段落呼吸";
    readonly content: "# 注意力动线、比例带与段落呼吸\n\n先画能量图，不急着列标题：\n\n`为什么在意 → 到底是什么 → 真实使用怎样 → 它意味着什么 → 读者带走什么`\n\n每一段承担一个主要动作：观察、解释、验证、转折、判断或回望。信息密集的解释之后安排场景、反应、画面或短判断；小标题承载发现、问题或判断，不做功能目录。转场可通过镜头拉近或拉远完成：从动作到界面，从界面到机制，再从机制回到生活。\n\n### 产品体验类\n\n`小动作或第一反应 → 多组真实体验 → 技术拆解 → 摩擦与取舍 → 有条件的喜欢或拒绝 → 回到原来的习惯`\n\n场景与进入 8–15%，使用体验与产品细节 35–50%，机制解释或对比 15–25%，摩擦、限制与判断 15–25%，结尾与余味 5–10%。\n\n### 技术解释类\n\n`熟悉的问题 → 具体事件或产品信号 → 机制／历史 → 案例或不同方案 → 尚未解决的障碍 → 克制的方向判断`\n\n熟悉入口 8–12%，背景与机制 30–40%，案例与产品信号 25–35%，障碍与判断 15–22%，结尾 5–10%。\n\n### 推荐与清单类\n\n`编辑品味或现实需要 → 每个产品的一幅小型生活画像 → 选择之间的差异 → 按人群给捷径 → 轻轻收尾`\n\n编辑选择标准 8–12%，产品小画像 65–78%，交叉判断 10–18%，结尾 3–7%。\n\n比例控制文章空间，不控制章节数量；允许约 ±5–10% 浮动，原始材料优先。";
}, {
    readonly id: "product-review-route";
    readonly title: "产品体验与对比路线";
    readonly content: "# 产品体验与对比路线\n\n适用于上手体验、对比、AI 工具测试和压力测试。读者决定只能选择一个：采用、替换、付费、推荐、等待或理解可靠边界。\n\n推进方式：具体任务或反常结果 → 说明任务为何检验核心承诺 → 展开真实体验和必要机制 → 在有意义时比较旧工作流或公平替代项 → 保留会改变结论的失败、摩擦、成本、隐私问题或人工修正 → 说明谁受益、谁应跳过、什么仍未测试。\n\n量化只在它真实改变判断时出现。评分必须有量表与样本，初体验不能声称长期可靠性，商业关系必须披露。";
}, {
    readonly id: "update-explainer-route";
    readonly title: "版本与发布解读路线";
    readonly content: "# 版本与发布解读路线\n\n适用于系统更新、应用版本和“是否值得升级”。先选择一个决定：现在升级、等待稳定、理解关键变化，或准备工作流与兼容性调整。\n\n写清版本、状态、支持范围和观察来源。按用户后果而非更新日志顺序组织：变化及其当下意义 → 真正改变高频行为的细节 → 可见功能与底层变化 → 兼容性、性能、稳定性、迁移、价格或数据风险 → 按读者类型给出决定。不要把已宣布但未可用的功能写成实测。";
}, {
    readonly id: "technology-explainer-route";
    readonly title: "技术机制与行业变化路线";
    readonly content: "# 技术机制与行业变化路线\n\n适用于机制、标准、安全变化、行业动向和支持更大判断的产品信号。推进方式：熟悉摩擦或具体事件 → 只解释到足以理解后果的机制 → 用案例或比较揭示模式 → 说出技术、经济、可用性、安全或治理障碍 → 把方向判断明确写成有依据的推论。\n\n技术主张优先使用一手资料。保留会改变判断的名称和因果关系，用例子翻译机制，不拿类比替代机制，也不把单一设计放大成行业共识。";
}, {
    readonly id: "recommendation-route";
    readonly title: "工具与工作流推荐路线";
    readonly content: "# 工具与工作流推荐路线\n\n围绕一个具体使用情景，帮助读者选择、安装、尝试、付费或拒绝工具。先公开选择标准，再把每项写成“使用处境／区别性动作／可观察收益／成本或限制／适合人群”的小型生活画像，最后比较重叠选择并给出人群捷径。\n\n不要照抄商店摘要，不为凑数保留弱项，不把赞助伪装成编辑选择，也不称所有产品都适合所有人。";
}, {
    readonly id: "evidence-standard";
    readonly title: "事实底稿、证据与视觉证明";
    readonly content: "# 事实底稿、证据与视觉证明\n\n先分开：已确认事实和产品行为、真实场景与体验、作者有资格作出的解释判断、尚未确认或禁止延伸的主张。每个重要主张记录 `主张 → 证据类型 → 可观察细节 → 适用范围 → 置信度`。\n\n证据可以是直接操作、界面结果、明确范围的重复使用、同任务对比、测量输出、官方资料、可归属引语、带方法的用户研究，或失败与人工接管。质性观察是有效支持，不需要为了专业感强行添加数字。\n\n截图、录屏和图示应紧邻它证明的判断，并标明产品动作、输入、结果或比较关系。设备照片和装饰图不能证明软件行为。缺少关键事实时，补最小测试、请求材料或收窄主张，不把文章润色成无依据的确定性。";
}, {
    readonly id: "style-migration-protocol";
    readonly title: "宏观—中观—微观文风迁移";
    readonly content: "# 宏观—中观—微观文风迁移\n\n### 第一遍：宏观层\n\n删除与编辑目光无关的功能罗列；让开头从真实问题、具体变化、小动作、熟悉摩擦、改观瞬间或有证据的惊喜进入；让体验、解释、判断和收束存在因果或情绪推进；把重要判断放在材料足够之后。\n\n### 第二遍：中观层\n\n让每段承担一个主要动作；长短、轻重与信息密度有变化；密集解释后给场景、反应或短判断；段尾为下一段留下问题、反差、结果或情绪余波；限制若会改变作者与产品的关系，应在赞美尚未结束时出现。\n\n### 第三遍：微观层\n\n用具体动作、对象、界面和后果替代空泛形容词；技术名词在解释因果时保留，周围句法自然；允许短句落锤，也允许长句完成解释；幽默来自真实行为、奇怪输出或作者处境。\n\n最后搜索“不是……而是……”“不在于……而在于……”“不只……还……”“真正……的是……”。开头最多保留一个不可替代的对比句，正文只保留真实排他关系，其余改为直接判断、因果说明或具体场景。\n\n完成后做解耦检查：去掉产品名，编辑目光是否仍在；去掉标题，段落是否仍像同一位编辑安排；去掉数字，观察和判断是否仍成立；去掉温暖形容词，场景和句法是否仍有温度；去掉无依据的第一人称，作者是否仍通过选择、解释和判断在场。";
}, {
    readonly id: "voice-and-structure";
    readonly title: "句子声音、标题与结尾";
    readonly content: "# 句子声音、标题与结尾\n\n采用技术熟悉、好奇而克制的编辑声音：亲近但不装熟，果断但不隐藏不确定性，宣传强度不超过事实。具体名词、动作、界面状态、输入输出、失败与取舍承担质感；技术名词保留必要因果，少用抽象褒义词。\n\n句长和段长随思考变化。信息密集段落之间可穿插短而有依据的观察；有记忆点的句子只负责压缩已经积累起来的感受或判断，不提前宣告“这很重要”。括号偶尔展示思绪，不作为填充。\n\n标题可组合产品或事件、可见条件、读者决定和真实限制带来的张力，但数字、时长、比较和结论必须由正文证明。结尾回到开场物件、人的处境或读者决定，最多给一个克制行动，不突然上升到“科技与人类”。";
}, {
    readonly id: "style-similarity-audit";
    readonly title: "整体文风相似度审查";
    readonly content: "# 整体文风相似度审查\n\n评估的是生成方法相似度，不是词句重合度。真实门失败时先退回，不进入风格计分。\n\n百分制：编辑目光 20；叙述者与读者关系 15；人的温度与情绪运动 15；宏观动线 15；段落呼吸 15；微观语言 15；外层包装 5。90 分以上表示方法迁移可信；80–89 表示风格可辨但有一层偏弱；70–79 仍有通用产品文案感；低于 70 多为表面模仿。分数用于定位，不机械决定发布。\n\n发现漂移时依次检查：选材与编辑目光 → 叙述者和读者距离 → 情绪真实性 → 宏观结构 → 中观节奏 → 句子声音 → 标题包装。只修最早漂移层；上层错误时不要先润色句子。\n\n伪相似信号包括：复刻标题或原句、强行添加“我用了一周”、用任意数字制造专业感、有俏皮话却无观察、开头讲人而正文退化为发布稿、连续短段和对比句制造节奏、与前文无关的抒情结尾。\n\n审查输出应包含真实状态、总分与分项依据、首要漂移层、三项优先修改；示例改法只在确实帮助理解时提供。";
}, {
    readonly id: "annotated-sample-cards";
    readonly title: "样本机制使用边界";
    readonly content: "# 样本机制使用边界\n\n选择结构或诊断风格时，只借编辑机制，不借标题、句式、人物、结论或具体事实。可复用的机制包括：以可见微动作进入体验；先积累具体产品信号再把预测标成推论；按用户后果组织版本解读；在推荐中保留同题比较、失败和独立判断；让标题中的测试规模对应公开方法；在技术解释中从人的后果进入，同时保留尚未解决的障碍。\n\n教程、产品故事、体验、解释、推荐和官方产品立场的选材逻辑不同。先确认主导类型，再选择机制，不能把样本拼成统一模板。";
}];
